package classification

import (
	"fmt"
	"sort"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
)

// PreloadKnowledgeBases materializes every KB referenced by this classifier.
// Stable ordering makes startup diagnostics deterministic.
func (c *Classifier) PreloadKnowledgeBases() error {
	if c == nil || len(c.kbClassifiers) == 0 {
		return nil
	}
	names := make([]string, 0, len(c.kbClassifiers))
	for name := range c.kbClassifiers {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		if err := c.kbClassifiers[name].Preload(); err != nil {
			return fmt.Errorf("preload knowledge base %q: %w", name, err)
		}
	}
	return nil
}

// Classifier handles text classification, model selection, and jailbreak detection functionality
type Classifier struct {
	// Dependencies - In-tree classifiers
	categoryInitializer         CategoryInitializer
	categoryInference           CategoryInference
	jailbreakInitializer        JailbreakInitializer
	jailbreakInference          JailbreakInference
	piiInitializer              PIIInitializer
	piiInference                PIIInference
	keywordClassifier           *KeywordClassifier
	keywordEmbeddingInitializer EmbeddingClassifierInitializer
	keywordEmbeddingClassifier  *EmbeddingClassifier

	// Dependencies - MCP-based classifiers
	mcpCategoryInitializer MCPCategoryInitializer
	mcpCategoryInference   MCPCategoryInference

	// Hallucination mitigation classifiers
	factCheckClassifier           *FactCheckClassifier
	hallucinationDetector         *HallucinationDetector
	endpointHallucinationDetector *EndpointHallucinationDetector
	feedbackDetector              *FeedbackDetector
	reaskClassifier               *ReaskClassifier

	// Preference classifier for route matching via external LLM
	preferenceClassifier *PreferenceClassifier

	// Language classifier
	languageClassifier *LanguageClassifier

	// Context classifier for token count-based routing
	contextClassifier *ContextClassifier
	// tokenCalibrator learns provider-specific prompt token ratios for context routing.
	tokenCalibrator *CalibratedTokenCounter

	// Structure classifier for request-shape routing signals
	structureClassifier *StructureClassifier

	// Complexity classifier for complexity-based routing using embedding similarity
	complexityClassifier *ComplexityClassifier

	// Event classifier for event-driven request routing
	eventClassifier *EventClassifier

	// Contrastive jailbreak classifiers keyed by rule name.
	// Only populated for JailbreakRules with Method == "contrastive".
	contrastiveJailbreakClassifiers map[string]*ContrastiveJailbreakClassifier

	// Authz classifier for user-level authorization signal classification
	authzClassifier *AuthzClassifier

	// Knowledge-base classifiers keyed by configured KB name.
	kbClassifiers      map[string]*KnowledgeBaseClassifier
	genericClassifiers map[string]labelClassifier
	// Identity header names resolved from authz.identity config (or defaults).
	// Used by EvaluateAllSignalsWithHeaders to read user identity from requests.
	authzUserIDHeader     string
	authzUserGroupsHeader string
	// authzFailOpen: cfg.Authz.FailOpen; see applyAuthzFailOpenOnClassifyError.
	authzFailOpen bool

	Config           *config.RouterConfig
	CategoryMapping  *CategoryMapping
	PIIMapping       *PIIMapping
	JailbreakMapping *JailbreakMapping

	// Category name mapping layer to support generic categories in config
	// Maps MMLU-Pro category names -> generic category names (as defined in config.Categories)
	MMLUToGeneric map[string]string
	// Maps generic category names -> MMLU-Pro category names
	GenericToMMLU map[string][]string
}

type option func(*Classifier)

func withCategory(categoryMapping *CategoryMapping, categoryInitializer CategoryInitializer, categoryInference CategoryInference) option {
	return func(c *Classifier) {
		c.CategoryMapping = categoryMapping
		c.categoryInitializer = categoryInitializer
		c.categoryInference = categoryInference
	}
}

func withJailbreak(jailbreakMapping *JailbreakMapping, jailbreakInitializer JailbreakInitializer, jailbreakInference JailbreakInference) option {
	return func(c *Classifier) {
		c.JailbreakMapping = jailbreakMapping
		c.jailbreakInitializer = jailbreakInitializer
		c.jailbreakInference = jailbreakInference
	}
}

func withPII(piiMapping *PIIMapping, piiInitializer PIIInitializer, piiInference PIIInference) option {
	return func(c *Classifier) {
		c.PIIMapping = piiMapping
		c.piiInitializer = piiInitializer
		c.piiInference = piiInference
	}
}

func withKeywordClassifier(keywordClassifier *KeywordClassifier) option {
	return func(c *Classifier) {
		c.keywordClassifier = keywordClassifier
	}
}

func withKeywordEmbeddingClassifier(keywordEmbeddingInitializer EmbeddingClassifierInitializer, keywordEmbeddingClassifier *EmbeddingClassifier) option {
	return func(c *Classifier) {
		c.keywordEmbeddingInitializer = keywordEmbeddingInitializer
		c.keywordEmbeddingClassifier = keywordEmbeddingClassifier
	}
}

func withReaskClassifier(reaskClassifier *ReaskClassifier) option {
	return func(c *Classifier) {
		c.reaskClassifier = reaskClassifier
	}
}

func withKBClassifiers(classifiers map[string]*KnowledgeBaseClassifier) option {
	return func(c *Classifier) {
		c.kbClassifiers = classifiers
	}
}

func withStructureClassifier(structureClassifier *StructureClassifier) option {
	return func(c *Classifier) {
		c.structureClassifier = structureClassifier
	}
}

func withComplexityClassifier(complexityClassifier *ComplexityClassifier) option {
	return func(c *Classifier) {
		c.complexityClassifier = complexityClassifier
	}
}

func withEventClassifier(eventClassifier *EventClassifier) option {
	return func(c *Classifier) {
		c.eventClassifier = eventClassifier
	}
}

func withContrastiveJailbreakClassifiers(classifiers map[string]*ContrastiveJailbreakClassifier) option {
	return func(c *Classifier) {
		c.contrastiveJailbreakClassifiers = classifiers
	}
}

func withAuthzClassifier(authzClassifier *AuthzClassifier) option {
	return func(c *Classifier) {
		c.authzClassifier = authzClassifier
	}
}

// newClassifierWithOptions creates a new classifier with the given options
func newClassifierWithOptions(cfg *config.RouterConfig, options ...option) (*Classifier, error) {
	if cfg == nil {
		return nil, fmt.Errorf("config is nil")
	}

	classifier := &Classifier{Config: cfg}

	// Resolve identity header names from authz.identity config (or defaults).
	classifier.authzUserIDHeader = cfg.Authz.Identity.GetUserIDHeader()
	classifier.authzUserGroupsHeader = cfg.Authz.Identity.GetUserGroupsHeader()
	classifier.authzFailOpen = cfg.Authz.FailOpen

	for _, option := range options {
		option(classifier)
	}

	// Build category name mappings to support generic categories in config
	classifier.buildCategoryNameMappings()

	return classifier, nil
}

package classification

// EvaluateAllSignals evaluates all signal types and returns SignalResults
// This is the new method that includes fact_check signals
func (c *Classifier) EvaluateAllSignals(text string) *SignalResults {
	return c.EvaluateAllSignalsWithContext(text, text, text, nil, nil, false, false, "", nil, ConversationFacts{}, "")
}

// EvaluateAllSignalsWithForceOption evaluates signals with option to force evaluate all
// forceEvaluateAll: if true, evaluates all configured signals regardless of decision usage
func (c *Classifier) EvaluateAllSignalsWithForceOption(text string, forceEvaluateAll bool) *SignalResults {
	return c.EvaluateAllSignalsWithContext(text, text, text, nil, nil, false, forceEvaluateAll, "", nil, ConversationFacts{}, "")
}

package classification

import (
	"fmt"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/decision"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

// EvaluateDecisionWithEngine evaluates all decisions using pre-computed signals.
// Accepts SignalResults to avoid duplicate signal computation.
func (c *Classifier) EvaluateDecisionWithEngine(signals *SignalResults) (*decision.DecisionResult, error) {
	result, _, err := c.evaluateDecisionInternal(signals, false, nil)
	return result, err
}

// EvaluateDecisionWithEngineForDecisions evaluates only the supplied decision candidates.
func (c *Classifier) EvaluateDecisionWithEngineForDecisions(signals *SignalResults, decisions []config.Decision) (*decision.DecisionResult, error) {
	result, _, err := c.evaluateDecisionInternal(signals, false, decisions)
	return result, err
}

// EvaluateDecisionWithEngineAndTrace evaluates decisions and returns a
// per-decision trace tree that mirrors the boolean expression structure.
func (c *Classifier) EvaluateDecisionWithEngineAndTrace(signals *SignalResults) (*decision.DecisionResult, []decision.DecisionTrace, error) {
	return c.evaluateDecisionInternal(signals, true, nil)
}

// EvaluateDecisionWithEngineAndTraceForDecisions evaluates only the supplied
// decision candidates and returns their trace trees.
func (c *Classifier) EvaluateDecisionWithEngineAndTraceForDecisions(
	signals *SignalResults,
	decisions []config.Decision,
) (*decision.DecisionResult, []decision.DecisionTrace, error) {
	return c.evaluateDecisionInternal(signals, true, decisions)
}

func (c *Classifier) evaluateDecisionInternal(signals *SignalResults, trace bool, candidates []config.Decision) (*decision.DecisionResult, []decision.DecisionTrace, error) {
	decisions := c.Config.Decisions
	if candidates != nil {
		decisions = candidates
	}
	if len(decisions) == 0 {
		return nil, nil, fmt.Errorf("no decisions configured")
	}

	logging.Debugf("Signal evaluation results: keyword=%v, embedding=%v, domain=%v, fact_check=%v, user_feedback=%v, reask=%v, preference=%v, language=%v, context=%v, structure=%v, complexity=%v, modality=%v, authz=%v, jailbreak=%v, pii=%v, kb=%v, conversation=%v, event=%v",
		signals.MatchedKeywordRules, signals.MatchedEmbeddingRules, signals.MatchedDomainRules,
		signals.MatchedFactCheckRules, signals.MatchedUserFeedbackRules, signals.MatchedReaskRules, signals.MatchedPreferenceRules,
		signals.MatchedLanguageRules, signals.MatchedContextRules, signals.MatchedStructureRules,
		signals.MatchedComplexityRules, signals.MatchedModalityRules, signals.MatchedAuthzRules,
		signals.MatchedJailbreakRules, signals.MatchedPIIRules, signals.MatchedKBRules,
		signals.MatchedConversationRules, signals.MatchedEventRules)

	engine := decision.NewDecisionEngine(
		c.Config.KeywordRules,
		c.Config.EmbeddingRules,
		c.Config.Categories,
		decisions,
		c.Config.Strategy,
	).WithRoutingScope(c.Config.RoutingScope)

	sm := &decision.SignalMatches{
		KeywordRules:      signals.MatchedKeywordRules,
		EmbeddingRules:    signals.MatchedEmbeddingRules,
		DomainRules:       signals.MatchedDomainRules,
		FactCheckRules:    signals.MatchedFactCheckRules,
		UserFeedbackRules: signals.MatchedUserFeedbackRules,
		ReaskRules:        signals.MatchedReaskRules,
		PreferenceRules:   signals.MatchedPreferenceRules,
		LanguageRules:     signals.MatchedLanguageRules,
		ContextRules:      signals.MatchedContextRules,
		StructureRules:    signals.MatchedStructureRules,
		ComplexityRules:   signals.MatchedComplexityRules,
		ModalityRules:     signals.MatchedModalityRules,
		SignalConfidences: signals.SignalConfidences,
		AuthzRules:        signals.MatchedAuthzRules,
		JailbreakRules:    signals.MatchedJailbreakRules,
		PIIRules:          signals.MatchedPIIRules,
		KBRules:           signals.MatchedKBRules,
		ConversationRules: signals.MatchedConversationRules,
		EventRules:        signals.MatchedEventRules,
		MetadataRules:     signals.MatchedMetadataRules,
		ClassifierRules:   signals.MatchedClassifierRules,
		ProjectionRules:   signals.MatchedProjectionRules,
		SignalValues:      signals.SignalValues,
		SignalErrors:      signals.SignalErrors,
	}

	var result *decision.DecisionResult
	var traces []decision.DecisionTrace

	if trace {
		result, traces = engine.EvaluateDecisionsWithTrace(sm)
	} else {
		var err error
		result, err = engine.EvaluateDecisionsWithSignals(sm)
		if err != nil {
			return nil, nil, fmt.Errorf("decision evaluation failed: %w", err)
		}
	}

	if result == nil {
		return nil, traces, nil
	}

	result.MatchedKeywords = signals.MatchedKeywords

	logging.Debugf("Decision evaluation result: decision=%s, confidence=%.3f, matched_rules=%v, matched_keywords=%v",
		result.Decision.Name, result.Confidence, result.MatchedRules, result.MatchedKeywords)

	return result, traces, nil
}

package classification

import (
	"sync"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

// signalReadiness returns a map indicating whether each signal type's infrastructure is ready.
// Separated from EvaluateAllSignalsWithContext to keep cyclomatic complexity under the linter limit.
func (c *Classifier) signalReadiness() map[string]bool {
	return map[string]bool{
		config.SignalTypeKeyword:      c.keywordClassifier != nil,
		config.SignalTypeEmbedding:    c.keywordEmbeddingClassifier != nil,
		config.SignalTypeDomain:       c.IsCategoryEnabled() && c.categoryInference != nil && c.CategoryMapping != nil,
		config.SignalTypeFactCheck:    len(c.Config.FactCheckRules) > 0 && c.IsFactCheckEnabled(),
		config.SignalTypeUserFeedback: len(c.Config.UserFeedbackRules) > 0 && c.IsFeedbackDetectorEnabled(),
		config.SignalTypeReask:        c.reaskClassifier != nil,
		config.SignalTypePreference:   len(c.Config.PreferenceRules) > 0 && c.IsPreferenceClassifierEnabled(),
		config.SignalTypeLanguage:     len(c.Config.LanguageRules) > 0 && c.IsLanguageEnabled(),
		config.SignalTypeContext:      c.contextClassifier != nil,
		config.SignalTypeStructure:    c.structureClassifier != nil,
		config.SignalTypeComplexity:   c.complexityClassifier != nil,
		config.SignalTypeModality:     len(c.Config.ModalityRules) > 0 && c.Config.ModalityDetector.Enabled,
		config.SignalTypeJailbreak:    len(c.Config.JailbreakRules) > 0 && c.IsJailbreakEnabled(),
		config.SignalTypePII:          len(c.Config.PIIRules) > 0 && c.IsPIIEnabled(),
		config.SignalTypeKB:           len(c.kbClassifiers) > 0,
		config.SignalTypeConversation: len(c.Config.ConversationRules) > 0,
		config.SignalTypeEvent:        c.eventClassifier != nil,
		config.SignalTypeMetadata:     len(c.Config.MetadataRules) > 0,
		config.SignalTypeClassifier:   len(c.genericClassifiers) > 0,
	}
}

// textForSignalFunc returns a function that resolves the correct text for a given signal type,
// using uncompressed text for signals that must not receive compressed input.
func textForSignalFunc(text, uncompressedText string, skipCompressionSignals map[string]bool) func(string) string {
	return func(signalType string) string {
		resolved := text
		if uncompressedText != "" && skipCompressionSignals[signalType] {
			resolved = uncompressedText
		}
		return textForRoutingSignal(signalType, resolved)
	}
}

// EvaluateAllSignalsWithContext evaluates all signal types with separate text for context counting.
//
// text: (possibly compressed) text for signal evaluation
// contextText: text for context token counting (usually all messages combined)
// nonUserMessages: conversation history for jailbreak/PII with include_history
// forceEvaluateAll: if true, evaluates all configured signals regardless of decision usage
// uncompressedText: original text before prompt compression (empty = no compression happened)
// skipCompressionSignals: signal types that must use uncompressedText instead of text
// imageURL: image URL for multimodal signals ("" when the request carries no image)
func (c *Classifier) EvaluateAllSignalsWithContext(text string, contextText string, currentUserText string, priorUserMessages []string, nonUserMessages []string, hasPriorAssistantReply bool, forceEvaluateAll bool, uncompressedText string, skipCompressionSignals map[string]bool, convFacts ConversationFacts, imageURL string) *SignalResults {
	return c.EvaluateAllSignalsWithRequestFacts(
		text,
		contextText,
		currentUserText,
		priorUserMessages,
		nonUserMessages,
		hasPriorAssistantReply,
		forceEvaluateAll,
		uncompressedText,
		skipCompressionSignals,
		convFacts,
		imageURL,
		RequestFacts{},
	)
}

// EvaluateAllSignalsWithRequestFacts extends context-aware evaluation with
// bounded request-envelope facts used by metadata and conversation signals.
func (c *Classifier) EvaluateAllSignalsWithRequestFacts(
	text string,
	contextText string,
	currentUserText string,
	priorUserMessages []string,
	nonUserMessages []string,
	hasPriorAssistantReply bool,
	forceEvaluateAll bool,
	uncompressedText string,
	skipCompressionSignals map[string]bool,
	convFacts ConversationFacts,
	imageURL string,
	requestFacts RequestFacts,
) *SignalResults {
	return c.evaluateAllSignalsWithContext(
		text,
		contextText,
		currentUserText,
		priorUserMessages,
		nonUserMessages,
		hasPriorAssistantReply,
		forceEvaluateAll,
		uncompressedText,
		skipCompressionSignals,
		convFacts,
		imageURL,
		requestFacts,
		nil,
		false,
	)
}

// EvaluateAllSignalsWithRequestFactsForDecisions scopes signal usage to one
// routing profile while carrying request-envelope facts.
func (c *Classifier) EvaluateAllSignalsWithRequestFactsForDecisions(
	text string,
	contextText string,
	currentUserText string,
	priorUserMessages []string,
	nonUserMessages []string,
	hasPriorAssistantReply bool,
	forceEvaluateAll bool,
	uncompressedText string,
	skipCompressionSignals map[string]bool,
	convFacts ConversationFacts,
	imageURL string,
	requestFacts RequestFacts,
	decisions []config.Decision,
) *SignalResults {
	return c.evaluateAllSignalsWithContext(
		text,
		contextText,
		currentUserText,
		priorUserMessages,
		nonUserMessages,
		hasPriorAssistantReply,
		forceEvaluateAll,
		uncompressedText,
		skipCompressionSignals,
		convFacts,
		imageURL,
		requestFacts,
		decisions,
		true,
	)
}

func (c *Classifier) evaluateAllSignalsWithContext(
	text string,
	contextText string,
	currentUserText string,
	priorUserMessages []string,
	nonUserMessages []string,
	hasPriorAssistantReply bool,
	forceEvaluateAll bool,
	uncompressedText string,
	skipCompressionSignals map[string]bool,
	convFacts ConversationFacts,
	imageURL string,
	requestFacts RequestFacts,
	signalScope []config.Decision,
	signalScopeSet bool,
) *SignalResults {
	defer c.enterSignalEvaluationLoadGate()()
	// Determine which signals (type:name) should be evaluated
	var usedSignals map[string]bool
	switch {
	case forceEvaluateAll:
		usedSignals = c.getAllSignalTypes()
		logging.Debugf("[Signal Computation] Force evaluate all signals mode enabled")
	case signalScopeSet:
		usedSignals = c.getUsedSignalsForDecisions(signalScope)
	default:
		usedSignals = c.getUsedSignals()
	}

	textForSignal := textForSignalFunc(text, uncompressedText, skipCompressionSignals)
	ready := c.signalReadiness()

	results := &SignalResults{
		Metrics:           &SignalMetricsCollection{},
		SignalConfidences: make(map[string]float64),
		SignalValues:      make(map[string]float64),
		SignalErrors:      make(map[string]string),
	}

	var wg sync.WaitGroup
	var mu sync.Mutex
	imgArg := imageURL

	// Allocate a request-scoped image embedding cache only when an image is
	// actually attached. Two signals - complexity (image rules) and embedding
	// (image-modality rules) - independently pull image embeddings via FFI;
	// the cache lets whichever runs first donate its result to the other,
	// turning two SigLIP forward passes into one. With no image attached,
	// neither signal touches the cache, so leaving it nil is correct.
	var imgCache *requestImageEmbeddingCache
	if imgArg != "" {
		imgCache = newRequestImageEmbeddingCache()
	}

	dispatchers := c.buildSignalDispatchers(
		results,
		&mu,
		textForSignal,
		contextText,
		currentUserText,
		priorUserMessages,
		nonUserMessages,
		hasPriorAssistantReply,
		imgArg,
		imgCache,
		convFacts,
		requestFacts,
		usedSignals,
	)
	runSignalDispatchers(dispatchers, usedSignals, ready, &wg)

	wg.Wait()
	results = c.applySignalGroups(results)
	results = c.applySignalComposers(results)
	results = c.applySignalOutputPolicies(results)
	results = c.applyProjections(results)
	return results
}

package classification

import (
	"sync"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

type signalDispatch struct {
	signalType string
	name       string
	evaluate   func()
}

func (c *Classifier) buildSignalDispatchers(
	results *SignalResults,
	mu *sync.Mutex,
	textForSignal func(string) string,
	contextText string,
	currentUserText string,
	priorUserMessages []string,
	nonUserMessages []string,
	hasPriorAssistantReply bool,
	imgArg string,
	imgCache *requestImageEmbeddingCache, // may be nil; both image-consuming evaluators handle nil via cache.resolve's nil-receiver fallthrough
	convFacts ConversationFacts,
	requestFacts RequestFacts,
	usedSignals map[string]bool,
) []signalDispatch {
	dispatchers := []signalDispatch{
		{
			config.SignalTypeKeyword, "Keyword",
			func() { c.evaluateKeywordSignal(results, mu, textForSignal(config.SignalTypeKeyword)) },
		},
		{
			config.SignalTypeEmbedding, "Embedding",
			func() {
				c.evaluateEmbeddingSignal(results, mu, textForSignal(config.SignalTypeEmbedding), imgArg, imgCache)
			},
		},
		{
			config.SignalTypeDomain, "Domain",
			func() { c.evaluateDomainSignal(results, mu, textForSignal(config.SignalTypeDomain)) },
		},
		{
			config.SignalTypeFactCheck, "Fact-check",
			func() { c.evaluateFactCheckSignal(results, mu, textForSignal(config.SignalTypeFactCheck)) },
		},
		{
			config.SignalTypeUserFeedback, "User feedback",
			func() {
				c.evaluateUserFeedbackSignal(
					results,
					mu,
					textForSignal(config.SignalTypeUserFeedback),
					hasPriorAssistantReply,
				)
			},
		},
		{
			config.SignalTypeReask, "Reask",
			func() { c.evaluateBoundedReaskSignal(results, mu, currentUserText, priorUserMessages) },
		},
		{
			config.SignalTypePreference, "Preference",
			func() { c.evaluatePreferenceSignal(results, mu, textForSignal(config.SignalTypePreference)) },
		},
		{
			config.SignalTypeLanguage, "Language",
			func() { c.evaluateLanguageSignal(results, mu, textForSignal(config.SignalTypeLanguage)) },
		},
		{
			config.SignalTypeContext, "Context",
			func() { c.evaluateContextSignal(results, mu, contextText) },
		},
		{
			config.SignalTypeStructure, "Structure",
			func() {
				c.evaluateStructureSignal(
					results,
					mu,
					textForSignal(config.SignalTypeStructure),
					currentUserText,
				)
			},
		},
		{
			config.SignalTypeComplexity, "Complexity",
			func() {
				c.evaluateComplexitySignal(results, mu, textForSignal(config.SignalTypeComplexity), imgArg, imgCache)
			},
		},
		{
			config.SignalTypeModality, "Modality",
			func() { c.evaluateModalitySignal(results, mu, textForSignal(config.SignalTypeModality)) },
		},
	}
	return append(
		dispatchers,
		c.buildPolicySignalDispatchers(
			results,
			mu,
			textForSignal,
			priorUserMessages,
			nonUserMessages,
			convFacts,
			requestFacts,
			usedSignals,
		)...,
	)
}

func (c *Classifier) evaluateBoundedReaskSignal(
	results *SignalResults,
	mu *sync.Mutex,
	currentUserText string,
	priorUserMessages []string,
) {
	c.evaluateReaskSignal(
		results,
		mu,
		textForRoutingSignal(config.SignalTypeReask, currentUserText),
		boundedReaskMessages(priorUserMessages),
	)
}

func boundedReaskMessages(messages []string) []string {
	bounded := make([]string, len(messages))
	for index, message := range messages {
		bounded[index] = textForRoutingSignal(config.SignalTypeReask, message)
	}
	return bounded
}

func runSignalDispatchers(dispatchers []signalDispatch, usedSignals map[string]bool, ready map[string]bool, wg *sync.WaitGroup) {
	for _, d := range dispatchers {
		if isSignalTypeUsed(usedSignals, d.signalType) && ready[d.signalType] {
			wg.Add(1)
			go func(dispatch signalDispatch) {
				defer wg.Done()
				dispatch.evaluate()
			}(d)
			continue
		}

		if !isSignalTypeUsed(usedSignals, d.signalType) {
			logging.Debugf("[Signal Computation] %s signal not used in any decision, skipping evaluation", d.name)
		}
	}
}

package classification

import (
	"sync"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
)

func (c *Classifier) buildPolicySignalDispatchers(
	results *SignalResults,
	mu *sync.Mutex,
	textForSignal func(string) string,
	priorUserMessages []string,
	nonUserMessages []string,
	convFacts ConversationFacts,
	requestFacts RequestFacts,
	usedSignals map[string]bool,
) []signalDispatch {
	var (
		history     []string
		historyOnce sync.Once
	)
	historyForSignals := func() []string {
		historyOnce.Do(func() {
			history = historyForHistoryAwareSignals(
				priorUserMessages,
				nonUserMessages,
			)
		})
		return history
	}
	return []signalDispatch{
		{
			config.SignalTypeJailbreak, "Jailbreak",
			func() {
				c.evaluateJailbreakSignal(
					results,
					mu,
					textForSignal(config.SignalTypeJailbreak),
					historyForSignals(),
				)
			},
		},
		{
			config.SignalTypePII, "PII",
			func() {
				c.evaluatePIISignal(
					results,
					mu,
					textForSignal(config.SignalTypePII),
					historyForSignals(),
				)
			},
		},
		{
			config.SignalTypeKB, "KB",
			func() { c.evaluateKBSignals(results, mu, textForSignal(config.SignalTypeKB)) },
		},
		{
			config.SignalTypeConversation, "Conversation",
			func() {
				c.evaluateConversationSignal(
					results,
					mu,
					convFacts,
					usedSignals,
				)
			},
		},
		{
			config.SignalTypeEvent, "Event",
			func() { c.evaluateEventSignal(results, mu, textForSignal(config.SignalTypeEvent)) },
		},
		{
			config.SignalTypeMetadata, "Metadata",
			func() { c.evaluateMetadataSignal(results, mu, requestFacts, usedSignals) },
		},
		{
			config.SignalTypeClassifier, "Classifier",
			func() {
				c.evaluateGenericClassifierSignals(
					results,
					mu,
					textForSignal(config.SignalTypeClassifier),
					usedSignals,
					requestFacts.Context,
				)
			},
		},
	}
}

