1	package extproc
2	
3	import (
4		"strings"
5		"time"
6	
7		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/classification"
8		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
9		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
10		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/selection"
11		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/sessiontelemetry"
12		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/utils/entropy"
13	)
14	
15	// performDecisionEvaluation performs decision evaluation using DecisionEngine
16	// Returns (decisionName, confidence, reasoningDecision, selectedModel)
17	// This is the new approach that uses Decision-based routing with AND/OR rule combinations
18	// Decision evaluation runs only for request-facing routing models. Concrete
19	// backend model IDs are passthrough requests: they do not inherit the default
20	// recipe's signals, policy, decisions, or plugins. Direct looper slugs use the
21	// default recipe while limiting candidates to their algorithm type.
22	func (r *OpenAIRouter) performDecisionEvaluation(originalModel string, history signalConversationHistory, ctx *RequestContext) (string, float64, entropy.ReasoningDecision, string, error) {
23		var decisionName string
24		var evaluationConfidence float64
25		var reasoningDecision entropy.ReasoningDecision
26		var selectedModel string
27	
28		// Check if there's content to evaluate
29		if len(history.nonUserMessages) == 0 && history.currentUserMessage == "" &&
30			!hasEnvelopeRoutingFacts(history) {
31			return "", 0.0, entropy.ReasoningDecision{}, "", nil
32		}
33	
34		// Focused callers may invoke this method without the normal pre-routing
35		// stage. Resolve here as an idempotent guard so the isolation boundary is
36		// never dependent on call order.
37		if !ctx.Routing.IsResolved() {
38			r.resolveEntrypointForRequest(originalModel, ctx)
39		}
40		if ctx.Routing.SelectedRecipe() == nil {
41			return "", 0.0, entropy.ReasoningDecision{}, "", nil
42		}
43	
44		// Check if decisions are configured in any routing profile; the flat
45		// Decisions field only carries the default recipe's.
46		if !r.Config.HasRoutingDecisions() {
47			if r.requestModelActsAsAuto(originalModel) {
48				logging.Warnf("No decisions configured, using default model")
49				return "", 0.0, entropy.ReasoningDecision{}, r.Config.DefaultModel, nil
50			}
51			return "", 0.0, entropy.ReasoningDecision{}, "", nil
52		}
53	
54		signalInput := r.prepareSignalEvaluationInput(history)
55		signalInput.requestFacts.Context = ctx.TraceContext
56		ctx.VSRConversationFacts = signalInput.conversationFacts
57		if signalInput.evaluationText == "" && !hasEnvelopeRoutingFacts(history) {
58			return "", 0.0, entropy.ReasoningDecision{}, "", nil
59		}
60	
61		candidates := r.decisionCandidatesForRequest(originalModel, ctx)
62		signals, authzErr := r.evaluateSignalsForDecision(originalModel, signalInput, history.nonUserMessages, ctx, candidates)
63		if authzErr != nil {
64			return "", 0, entropy.ReasoningDecision{}, "", authzErr
65		}
66	
67		result, defaultModel := r.runDecisionEngine(originalModel, ctx, signals, candidates)
68		if result == nil {
69			return "", 0.0, entropy.ReasoningDecision{}, defaultModel, nil
70		}
71	
72		decisionName, evaluationConfidence, reasoningDecision, selectedModel, err := r.finalizeDecisionEvaluation(
73			result,
74			originalModel,
75			history.currentUserMessage,
76			ctx,
77		)
78		return decisionName, evaluationConfidence, reasoningDecision, selectedModel, err
79	}
80	
81	func (r *OpenAIRouter) selectorForDecisionMethod(method selection.SelectionMethod, algorithm *config.AlgorithmConfig, ctx *RequestContext) selection.Selector {
82		if method == selection.MethodHybrid && algorithm != nil && algorithm.Hybrid != nil {
83			return r.newDecisionHybridSelector(algorithm.Hybrid, ctx)
84		}
85		if method == selection.MethodMultiFactor && algorithm != nil {
86			return r.newDecisionMultiFactorSelector(algorithm.MultiFactor)
87		}
88		if method == selection.MethodPrompt && algorithm != nil &&
89			algorithm.Prompt != nil {
90			return r.newDecisionPromptSelector(*algorithm.Prompt)
91		}
92		registry := r.modelSelectorForRequest(ctx)
93		if registry == nil {
94			return nil
95		}
96		selector, _ := registry.Get(method)
97		return selector
98	}
99	
100	func (r *OpenAIRouter) modelSelectorForRequest(ctx *RequestContext) *selection.Registry {
101		if r == nil {
102			return nil
103		}
104		if ctx != nil && ctx.Routing.RecipeName() != "" && r.RecipeModelSelectors != nil {
105			if registry, ok := r.RecipeModelSelectors[ctx.Routing.RecipeName()]; ok {
106				return registry
107			}
108			return nil
109		}
110		return r.ModelSelector
111	}
112	
113	func (r *OpenAIRouter) newDecisionMultiFactorSelector(decisionCfg *config.MultiFactorSelectionConfig) selection.Selector {
114		selector := selection.NewMultiFactorSelector(buildMultiFactorSelectionConfig(decisionCfg))
115		if r != nil && r.Config != nil && r.Config.ModelConfig != nil {
116			selector.InitializeFromConfig(r.Config.ModelConfig)
117		}
118		return selector
119	}
120	
121	func (r *OpenAIRouter) newDecisionHybridSelector(decisionCfg *config.HybridSelectionConfig, ctx *RequestContext) selection.Selector {
122		var cfg *selection.HybridConfig
123		if r != nil && r.Config != nil {
124			cfg = buildHybridSelectionConfig(r.Config, decisionCfg)
125		} else {
126			cfg = selection.DefaultHybridConfig()
127		}
128	
129		eloSelector, routerDCSelector, autoMixSelector := r.hybridComponentSelectors(r.modelSelectorForRequest(ctx))
130	
131		selector := selection.NewHybridSelectorWithComponents(cfg, eloSelector, routerDCSelector, autoMixSelector)
132		r.applyHybridModelCosts(selector)
133		if r != nil && r.LookupTable != nil {
134			selector.SetLookupTable(r.LookupTable)
135		}
136		return selector
137	}
138	
139	// hybridComponentSelectors resolves the underlying elo/routerDC/autoMix selectors
140	// that the hybrid selector composes, when they are registered on the router.
141	func (r *OpenAIRouter) hybridComponentSelectors(registry *selection.Registry) (*selection.EloSelector, *selection.RouterDCSelector, *selection.AutoMixSelector) {
142		if registry == nil {
143			return nil, nil, nil
144		}
145		var eloSelector *selection.EloSelector
146		var routerDCSelector *selection.RouterDCSelector
147		var autoMixSelector *selection.AutoMixSelector
148		if selector, ok := registry.Get(selection.MethodElo); ok {
149			eloSelector, _ = selector.(*selection.EloSelector)
150		}
151		if selector, ok := registry.Get(selection.MethodRouterDC); ok {
152			routerDCSelector, _ = selector.(*selection.RouterDCSelector)
153		}
154		if selector, ok := registry.Get(selection.MethodAutoMix); ok {
155			autoMixSelector, _ = selector.(*selection.AutoMixSelector)
156		}
157		return eloSelector, routerDCSelector, autoMixSelector
158	}
159	
160	// applyHybridModelCosts seeds per-model prompt pricing into the hybrid selector.
161	func (r *OpenAIRouter) applyHybridModelCosts(selector *selection.HybridSelector) {
162		if r == nil || r.Config == nil || r.Config.ModelConfig == nil {
163			return
164		}
165		for model, params := range r.Config.ModelConfig {
166			if params.Pricing.PromptPer1M > 0 {
167				selector.SetModelCost(model, params.Pricing.PromptPer1M)
168			}
169		}
170	}
171	
172	func selectedModelRefFromResult(selCtx *selection.SelectionContext, result *selection.SelectionResult) *config.ModelRef {
173		for i := range selCtx.CandidateModels {
174			if selCtx.CandidateModels[i].Model == result.SelectedModel {
175				return &selCtx.CandidateModels[i]
176			}
177			if result.Method != selection.MethodPrompt &&
178				selCtx.CandidateModels[i].LoRAName == result.SelectedModel {
179				return &selCtx.CandidateModels[i]
180			}
181		}
182		return nil
183	}
184	
185	func logSelectionResult(method selection.SelectionMethod, result *selection.SelectionResult, selected *config.ModelRef, learningApplied bool) {
186		if learningApplied {
187			logging.Infof(
188				"[ModelSelection] Router Learning adjusted selection to %s (base_method=%s, score=%.4f, confidence=%.2f)",
189				selected.Model,
190				method,
191				result.Score,
192				result.Confidence,
193			)
194			return
195		}
196		logging.Infof(
197			"[ModelSelection] Selected %s (method=%s, score=%.4f, confidence=%.2f)",
198			selected.Model,
199			method,
200			result.Score,
201			result.Confidence,
202		)
203	}
204	
205	func firstValidCandidateModelRef(selCtx *selection.SelectionContext) *config.ModelRef {
206		if selCtx == nil {
207			return nil
208		}
209		for i := range selCtx.CandidateModels {
210			if strings.TrimSpace(selCtx.CandidateModels[i].Model) != "" {
211				return &selCtx.CandidateModels[i]
212			}
213		}
214		return nil
215	}
216	
217	// buildSelectionContext assembles the runtime inputs shared by selection
218	// algorithms. Static policy comes from AlgorithmConfig; dynamic request-time
219	// signals stay in SelectionContext so selectors do not need to reach back into
220	// extproc state.
221	func (r *OpenAIRouter) buildSelectionContext(
222		modelRefs []config.ModelRef,
223		decisionName string,
224		query string,
225		algorithm *config.AlgorithmConfig,
226		categoryName string,
227		candidateIterations []config.CandidateIterationConfig,
228		reqCtx *RequestContext,
229	) *selection.SelectionContext {
230		costWeight, qualityWeight := r.getSelectionWeights(algorithm)
231		latencyAwareTPOTPercentile, latencyAwareTTFTPercentile := r.getLatencyAwarePercentiles(algorithm)
232	
233		sessionID, userID, conversationHistory := r.extractSessionContext(reqCtx)
234		var recipeName config.RecipeName
235		if reqCtx != nil {
236			recipeName = reqCtx.Routing.RecipeName()
237		}
238	
239		return &selection.SelectionContext{
240			Query:                      query,
241			DecisionName:               decisionName,
242			RecipeName:                 recipeName,
243			CategoryName:               categoryName,
244			CandidateModels:            modelRefs,
245			CandidateIterations:        candidateIterations,
246			CostWeight:                 costWeight,
247			QualityWeight:              qualityWeight,
248			LatencyAwareTPOTPercentile: latencyAwareTPOTPercentile,
249			LatencyAwareTTFTPercentile: latencyAwareTTFTPercentile,
250			UserID:                     userID,
251			SessionID:                  sessionID,
252			AgenticSession:             r.buildAgenticSessionContext(reqCtx, modelRefs, sessionID, userID),
253			ConversationHistory:        conversationHistory,
254			CacheAffinityCtx:           r.buildCacheAffinityContext(reqCtx, modelRefs),
255		}
256	}
257	
258	func (r *OpenAIRouter) buildAgenticSessionContext(
259		reqCtx *RequestContext,
260		modelRefs []config.ModelRef,
261		sessionID string,
262		userID string,
263	) *selection.AgenticSessionContext {
264		if reqCtx == nil {
265			return nil
266		}
267		now := time.Now()
268		stateSessionID := config.RoutingNamespaceKey(reqCtx.Routing.RecipeName(), sessionID)
269		snapshot, hasMemory := sessiontelemetry.GetRouterSessionSnapshot(stateSessionID, now)
270		previousModel := reqCtx.PreviousModel
271		if previousModel == "" && hasMemory {
272			previousModel = snapshot.CurrentModel
273		}
274		idleFor := time.Duration(reqCtx.SessionIdleSeconds * float64(time.Second))
275		idleKnown := reqCtx.SessionIdleKnown
276		if hasMemory {
277			idleFor = snapshot.IdleFor
278			idleKnown = true
279		}
280		cacheWarmth, cacheWarmthOK := r.agenticCacheWarmth(reqCtx, previousModel, snapshot, hasMemory, now)
281		facts := reqCtx.VSRConversationFacts
282		activeToolLoop := conversationFactsIndicateActiveToolLoop(facts)
283		hasNonPortableContext, nonPortableContextReason := nonPortableContextBinding(reqCtx)
284		phase := selection.AgenticPhaseUserTurn
285		if hasNonPortableContext {
286			phase = selection.AgenticPhaseProviderState
287		}
288		if activeToolLoop {
289			phase = selection.AgenticPhaseToolLoop
290		}
291		return &selection.AgenticSessionContext{
292			ID:                          sessionID,
293			UserID:                      userID,
294			TurnIndex:                   reqCtx.TurnIndex,
295			PreviousModel:               previousModel,
296			PreviousResponseID:          reqCtx.PreviousResponseID,
297			MemoryPresent:               hasMemory,
298			MemoryTurnCount:             snapshot.TurnCount,
299			MemorySwitchCount:           snapshot.SwitchCount,
300			MemoryModelTurnCnts:         snapshot.ModelTurns,
301			MemoryPromptTokens:          snapshot.CumulativePromptTokens,
302			MemoryCachedTokens:          snapshot.CumulativeCachedTokens,
303			MemoryEstimatedCachedTokens: snapshot.CumulativeEstimatedCachedTokens,
304			MemoryOutputTokens:          snapshot.CumulativeCompletionTokens,
305			MemoryCost:                  snapshot.CumulativeCost,
306			MemoryEstimatedCacheSavings: snapshot.CumulativeEstimatedCacheSavings,
307			MemoryCacheAccountingSource: snapshot.LastCacheAccountingSource,
308			LastDecisionName:            snapshot.LastDecisionName,
309			LastDecisionReason:          snapshot.LastDecisionReason,
310			HistoryTokens:               reqCtx.HistoryTokenCount,
311			ContextTokens:               reqCtx.VSRContextTokenCount,
312			IdleFor:                     idleFor,
313			IdleKnown:                   idleKnown,
314			CacheWarmth:                 cacheWarmth,
315			CacheWarmthOK:               cacheWarmthOK,
316			Phase:                       phase,
317			ActiveToolLoop:              activeToolLoop,
318			HasNonPortableContext:       hasNonPortableContext,
319			NonPortableContextReason:    nonPortableContextReason,
320			ToolCallCount:               facts.AssistantToolCallCount,
321			ToolResultCount:             facts.ToolResultCount,
322			ToolDefinitionCnt:           facts.ToolDefinitionCount,
323			ModelContextWindows:         r.modelContextWindows(modelRefs),
324		}
325	}
326	
327	func nonPortableContextBinding(reqCtx *RequestContext) (bool, string) {
328		if reqCtx == nil {
329			return false, ""
330		}
331		if strings.TrimSpace(reqCtx.PreviousResponseID) != "" {
332			return true, "previous_response_id"
333		}
334		return false, ""
335	}
336	
337	func conversationFactsIndicateActiveToolLoop(facts classification.ConversationFacts) bool {
338		return facts.LastMessageToolResult ||
339			facts.LastMessageRole == "tool" ||
340			facts.LastUserAfterToolResult ||
341			facts.AssistantToolCallCount > facts.ToolResultCount
342	}
343	
344	func (r *OpenAIRouter) agenticCacheWarmth(
345		reqCtx *RequestContext,
346		previousModel string,
347		snapshot sessiontelemetry.RouterSessionSnapshot,
348		hasMemory bool,
349		now time.Time,
350	) (float64, bool) {
351		cacheWarmth := reqCtx.CacheWarmthEstimate
352		cacheWarmthOK := cacheWarmth > 0
353		if ambient, ok := estimateGateCacheWarmth(previousModel, now); ok {
354			cacheWarmth = ambient
355			cacheWarmthOK = true
356		}
357		if hasMemory && snapshot.CumulativePromptTokens > 0 {
358			cachedRatio := float64(snapshot.CumulativeCachedTokens) / float64(snapshot.CumulativePromptTokens)
359			if cachedRatio > cacheWarmth {
360				cacheWarmth = cachedRatio
361				cacheWarmthOK = true
362			}
363		}
364		return cacheWarmth, cacheWarmthOK
365	}
366	
367	func (r *OpenAIRouter) modelContextWindows(modelRefs []config.ModelRef) map[string]int {
368		if r == nil || r.Config == nil || r.Config.ModelConfig == nil {
369			return nil
370		}
371		windows := make(map[string]int, len(modelRefs))
372		for _, ref := range modelRefs {
373			if params, ok := r.Config.ModelConfig[ref.Model]; ok {
374				windows[ref.Model] = params.ContextWindowSize
375			}
376		}
377		return windows
378	}
379	
380	// buildCacheAffinityContext extracts the pre-dispatch continuation signals used
381	// by the cache-affinity estimator. Nil request context cleanly disables the
382	// estimator without forcing call sites to add extra branching.
383	func (r *OpenAIRouter) buildCacheAffinityContext(reqCtx *RequestContext, modelRefs []config.ModelRef) *selection.CacheAffinityContext {
384		if reqCtx == nil {
385			return nil
386		}
387	
388		// Missing model window metadata is valid; the estimator treats it as a
389		// neutral fit score rather than as an error.
390		return &selection.CacheAffinityContext{
391			TurnIndex:           reqCtx.TurnIndex,
392			PreviousModel:       reqCtx.PreviousModel,
393			PreviousResponseID:  reqCtx.PreviousResponseID,
394			HistoryTokens:       reqCtx.HistoryTokenCount,
395			ContextTokens:       reqCtx.VSRContextTokenCount,
396			ModelContextWindows: r.modelContextWindows(modelRefs),
397		}
398	}
399	
400	// getSelectionMethod determines which selection algorithm to use.
401	// Per-decision algorithm is the primary configuration (aligned with looper pattern).
402	// Defaults to static selection if no algorithm is specified.
403	func (r *OpenAIRouter) getSelectionMethod(algorithm *config.AlgorithmConfig) selection.SelectionMethod {
404		if algorithm != nil && algorithm.Type != "" {
405			if method, ok := selectionMethodByAlgorithmType[algorithm.Type]; ok {
406				return method
407			}
408		}
409		return selection.MethodStatic
410	}
411	
412	// getSelectionWeights returns cost and quality weights based on algorithm config.
413	// Uses per-decision config only (aligned with looper pattern).
414	func (r *OpenAIRouter) getSelectionWeights(algorithm *config.AlgorithmConfig) (float64, float64) {
415		// Check per-decision algorithm config
416		if algorithm != nil {
417			if algorithm.AutoMix != nil && algorithm.AutoMix.CostQualityTradeoff > 0 {
418				cost := algorithm.AutoMix.CostQualityTradeoff
419				return cost, 1.0 - cost
420			}
421			if algorithm.Hybrid != nil && algorithm.Hybrid.CostWeight > 0 {
422				cost := algorithm.Hybrid.CostWeight
423				return cost, 1.0 - cost
424			}
425		}
426	
427		// Default: equal weighting (0.5 cost, 0.5 quality)
428		return 0.5, 0.5
429	}
430	
431	// getLatencyAwarePercentiles extracts TPOT/TTFT percentile settings for latency_aware selection.
432	// Returns (0, 0) when latency_aware is not configured for the decision.
433	func (r *OpenAIRouter) getLatencyAwarePercentiles(algorithm *config.AlgorithmConfig) (int, int) {
434		if algorithm == nil || algorithm.LatencyAware == nil {
435			return 0, 0
436		}
437		return algorithm.LatencyAware.TPOTPercentile, algorithm.LatencyAware.TTFTPercentile
438	}
439	
440	// extractSessionContext extracts session ID, user ID, and conversation history from the RequestContext.
441	func (r *OpenAIRouter) extractSessionContext(ctx *RequestContext) (sessionID, userID string, conversationHistory []string) {
442		if ctx == nil {
443			return "", "", nil
444		}
445		userID = extractUserID(ctx)
446		if ctx.ResponseAPICtx != nil && ctx.ResponseAPICtx.IsResponseAPIRequest {
447			return r.extractResponseAPISessionContext(ctx, userID)
448		}
449		if len(ctx.ChatCompletionMessages) > 0 {
450			return r.extractChatCompletionSessionContext(ctx, userID)
451		}
452		return ctx.SessionID, userID, nil
453	}
454	
455	func (r *OpenAIRouter) extractResponseAPISessionContext(ctx *RequestContext, userID string) (sessionID, userIDOut string, conversationHistory []string) {
456		sessionID = ctx.ResponseAPICtx.ConversationID
457		if ctx.ResponseAPICtx.ConversationHistory != nil {
458			for _, storedResp := range ctx.ResponseAPICtx.ConversationHistory {
459				for _, inItem := range storedResp.Input {
460					if content := extractContentFromInputItem(inItem); content != "" {
461						conversationHistory = append(conversationHistory, content)
462					}
463				}
464				for _, outItem := range storedResp.Output {
465					if content := extractContentFromOutputItem(outItem); content != "" {
466						conversationHistory = append(conversationHistory, content)
467					}
468				}
469			}
470		}
471		return sessionID, userID, conversationHistory
472	}
473	
474	func (r *OpenAIRouter) extractChatCompletionSessionContext(ctx *RequestContext, userID string) (sessionID, userIDOut string, conversationHistory []string) {
475		sessionID = ctx.SessionID
476		if sessionID == "" {
477			sessionID = deriveSessionIDFromMessages(ctx.ChatCompletionMessages, userID)
478		}
479		for i, msg := range ctx.ChatCompletionMessages {
480			if msg.Content != "" && i < len(ctx.ChatCompletionMessages)-1 {
481				conversationHistory = append(conversationHistory, msg.Content)
482			}
483		}
484		return sessionID, userID, conversationHistory
485	}
